package main
import("os";"path/filepath";"testing")
func TestLowStructuralControlsNoProjection(t *testing.T){base:=t.TempDir();input:=filepath.Join(base,"input.csv");if e:=os.WriteFile(input,structural_csv(4096),0600);e!=nil{t.Fatal(e)};good:=low_job{profile:"L0",column:"linear",input:input,output:filepath.Join(base,"fresh"),start:256,pre_end:128,stride:1024,native_increment:162,increment:165888,window:16,hop:4,sample_rate:55937.5/1024};if e:=good.prepare();e!=nil{t.Fatal(e)};variants:=map[string]func(*low_job){"stride":func(j *low_job){j.stride=512},"alias":func(j *low_job){j.native_increment=1186},"noPre":func(j *low_job){j.pre_end=0},"preBeyondStart":func(j *low_job){j.start=64},"existingOutput":func(j *low_job){j.output=base},"window":func(j *low_job){j.window=32},"hop":func(j *low_job){j.hop=8},"profile":func(j *low_job){j.profile="L4"}};for name,change:=range variants{t.Run(name,func(t *testing.T){j:=good;change(&j);if e:=j.prepare();e==nil{t.Fatal("invalid geometry accepted")}})};if _,e:=os.Stat(good.output);!os.IsNotExist(e){t.Fatal("structural validation wrote output")}}
